import test from 'node:test';
import assert from 'node:assert/strict';
import { createPersonal, saveWeight, weightSummary, saveSleep, sleepMinutes, saveEntry, archiveEntry, reviewDecision, saveMoment, toggleRoutine, closeDay, saveWater, undoWater } from './personal-state.js';
test('weight correction replaces the date and rejected input leaves it unchanged',()=>{const s=createPersonal();const n=s.weights.length;saveWeight(s,{date:'2026-09-09',kg:82,note:'reggel'});assert.equal(s.weights.length,n);assert.equal(weightSummary(s).latest.kg,82);assert.throws(()=>saveWeight(s,{date:'2026-09-09',kg:NaN}));assert.equal(weightSummary(s).latest.kg,82);assert.equal(weightSummary({...s,weights:[]}).average,null);});
test('overnight sleep uses both dates, subtracts awake time and edits once',()=>{const s=createPersonal();const row={date:'2026-09-09',bed:'2026-09-08T23:15',wake:'2026-09-09T06:57',awake:12,quality:8,note:'',factors:['late-meal']};assert.equal(sleepMinutes(row),450);saveSleep(s,row);saveSleep(s,{...row,awake:0});assert.equal(s.sleeps.filter(x=>x.date===row.date).length,1);assert.equal(sleepMinutes(s.sleeps.find(x=>x.date===row.date)),462);assert.throws(()=>saveSleep(s,{...row,wake:row.bed}));});
test('journal drafts save explicitly, updates preserve identity, archive is reversible',()=>{const s=createPersonal();const n=s.entries.length;const id=saveEntry(s,{kind:'note',date:s.date,text:'Egy gondolat'});assert.equal(s.entries.length,n+1);saveEntry(s,{id,kind:'note',date:s.date,text:'Pontosítva'});assert.equal(s.entries.length,n+1);archiveEntry(s,id,true);assert.equal(s.entries.find(x=>x.id===id).archived,true);archiveEntry(s,id,false);assert.equal(s.entries.find(x=>x.id===id).text,'Pontosítva');assert.throws(()=>saveEntry(s,{kind:'note',date:s.date,text:'  '}));});
test('decision review is separate from its original words',()=>{const s=createPersonal();const d=s.entries.find(x=>x.kind==='decision');const original=d.text;reviewDecision(s,d.id,'Kisebb lépés is elég volt.');assert.equal(d.text,original);assert.equal(d.review,'Kisebb lépés is elég volt.');});
test('checkin slots replace and derived routines cannot self-complete',()=>{const s=createPersonal();saveMoment(s,'nap',{energy:4,stress:6,body:5,mind:7,note:'Sűrű nap'});saveMoment(s,'nap',{energy:6,stress:5,body:6,mind:7,note:'Jobb'});assert.equal(Object.keys(s.moments).length,2);assert.throws(()=>saveMoment(s,'nap',{energy:11,stress:5,body:6,mind:7}));assert.equal(toggleRoutine(s,'sleep'),false);assert.equal(toggleRoutine(s,'sun'),true);assert.equal(toggleRoutine(s,'sun'),true);assert.equal(s.routines.find(x=>x.id==='sun').done,false);});
test('closing is explicit and repeat edits do not duplicate the reflection',()=>{const s=createPersonal();assert.equal(s.closing,null);closeDay(s,{keep:'A közös ebéd',release:'A sietség',tomorrow:'Egy nyugodt reggel'});closeDay(s,{keep:'A beszélgetés',release:'A sietség',tomorrow:'Egy nyugodt reggel'});assert.equal(s.entries.filter(e=>e.id==='day-close').length,1);assert.match(s.entries.find(e=>e.id==='day-close').text,/beszélgetés/);});
test('water undo affects only the last new log and never the seed baseline',()=>{const s=createPersonal();saveWater(s,250);assert.equal(s.water.reduce((a,b)=>a+b.ml,0),1500);undoWater(s);undoWater(s);assert.equal(s.water.reduce((a,b)=>a+b.ml,0),1250);assert.throws(()=>saveWater(s,-250));});
